FeatureScript 3112;
import(path : "onshape/std/geometry.fs", version : "3112.0");

// Fixture batch 173: probes: the poles of B-spline face blends between a floor and a cylinder, and of swept profile blends. Generated by tools/fixtures/gen-batch-173.mjs; do not edit.
// Each case builds its geometry at the origin and may return a map of values to check.

function numbersProbe(numbers) returns array
{
    var out = [];
    for (var i = 0; i < size(numbers); i += 1)
        out = append(out, roundToPrecision(numbers[i], 9));
    return out;
}

// Each face's area, its point and normal at the middle of its parameters, and, for a B-spline surface, its degrees,
// knots, weights and poles (rounded to 1e-6 mm).
function surfaceProbe(context is Context, faces is Query) returns array
{
    var out = [];
    const r = function(x) { return roundToPrecision(x, 6); };
    for (var f in evaluateQuery(context, faces))
    {
        const p = evFaceTangentPlane(context, { "face" : f, "parameter" : vector(0.5, 0.5) });
        var entry = { "area" : r(evArea(context, { "entities" : f }) / millimeter ^ 2),
                "middle" : [r(p.origin[0] / millimeter), r(p.origin[1] / millimeter), r(p.origin[2] / millimeter)],
                "normal" : [r(p.normal[0]), r(p.normal[1]), r(p.normal[2])] };
        const s = evSurfaceDefinition(context, { "face" : f });
        entry["type"] = s.surfaceType;
        if (s is BSplineSurface)
        {
            entry.degrees = [s.uDegree, s.vDegree];
            entry.uKnots = numbersProbe(s.uKnots);
            entry.vKnots = numbersProbe(s.vKnots);
            if (s.isRational)
                entry.weights = s.weights;
            var rows = [];
            for (var i = 0; i < size(s.controlPoints); i += 1)
            {
                var points = [];
                for (var j = 0; j < size(s.controlPoints[i]); j += 1)
                {
                    const q = s.controlPoints[i][j];
                    points = append(points, [r(q[0] / millimeter), r(q[1] / millimeter), r(q[2] / millimeter)]);
                }
                rows = append(rows, points);
            }
            entry.poles = rows;
        }
        out = append(out, entry);
    }
    return out;
}

// Each edge of the faces that isn't a line: its length, and for a B-spline curve its degree, knots, weights and
// poles (rounded to 1e-6 mm); otherwise its type.
function edgeProbe(context is Context, faces is Query) returns array
{
    var out = [];
    const r = function(x) { return roundToPrecision(x, 6); };
    for (var e in evaluateQuery(context, qOwnedByBody(faces, EntityType.EDGE)))
    {
        const c = evCurveDefinition(context, { "edge" : e, "returnBSplinesAsOther" : false });
        if (c is Line)
            continue;
        var entry = { "length" : r(evLength(context, { "entities" : e }) / millimeter) };
        if (c is BSplineCurve)
        {
            entry.degree = c.degree;
            entry.knots = numbersProbe(c.knots);
            if (c.isRational)
                entry.weights = c.weights;
            var points = [];
            for (var q in c.controlPoints)
                points = append(points, [r(q[0] / millimeter), r(q[1] / millimeter), r(q[2] / millimeter)]);
            entry.poles = points;
        }
        else
            entry["type"] = (c is Circle) ? "CIRCLE" : ((c is Ellipse) ? "ELLIPSE" : "OTHER");
        out = append(out, entry);
    }
    return out;
}

// face-blend: a floor and an upright cylinder (radius 10) blended with radii 3 and 5 (batch 172 c002): its poles
export function c001(context is Context, id is Id)
{
    const s1 = newSketchOnPlane(context, id + "s1", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(s1, "r1", { "firstCorner" : vector(-20, -20) * millimeter, "secondCorner" : vector(20, 20) * millimeter });
    skSolve(s1);
    const s2 = newSketchOnPlane(context, id + "s2", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skCircle(s2, "c1", { "center" : vector(0, 0) * millimeter, "radius" : 10 * millimeter });
    skSolve(s2);
    extrude(context, id + "cyl", { "bodyType" : ExtendedToolBodyType.SURFACE, "surfaceEntities" : qOwnedByBody(qBodyType(qCreatedBy(id + "s2", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), "endBound" : BoundingType.BLIND, "depth" : 20 * millimeter, "oppositeDirection" : false });
    faceBlend(context, id + "blend1", { "side1" : qOwnedByBody(qBodyType(qCreatedBy(id + "s1", EntityType.BODY), BodyType.SHEET), EntityType.FACE), "flipSide1" : false, "side2" : qOwnedByBody(qBodyType(qCreatedBy(id + "cyl", EntityType.BODY), BodyType.SHEET), EntityType.FACE), "flipSide2" : false, "radius" : 3 * millimeter, "propagation" : false, "crossSection" : FaceBlendCrossSection.ROLLING_BALL, "blendControlType" : BlendControlType.RADIUS, "asymmetric" : true, "crossSectionShape" : FaceBlendCrossSectionShape.CIRCULAR, "tangentHoldLines" : false, "conicHoldLines" : false, "hasCliffEdges" : false, "hasCaps" : false, "hasLimits" : false, "hasHelpPoint" : false, "trim" : FaceBlendTrimType.WALLS, "detach" : false, "showSelection" : false, "showIsocurves" : false, "secondRadius" : 5 * millimeter, "switchAsymmetric" : false });
    return { "faces" : surfaceProbe(context, qOwnedByBody(qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SHEET), EntityType.FACE)), "edges" : edgeProbe(context, qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SHEET)) };
}

