    skLineSegment(u1, "l1", { "start" : vector(0, 0) * millimeter, "end" : vector(30, 0) * millimeter });
    skSolve(u1);
    extrude(context, id + "upright", { "bodyType" : ExtendedToolBodyType.SURFACE, "surfaceEntities" : qOwnedByBody(qBodyType(qCreatedBy(id + "u1", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), "endBound" : BoundingType.BLIND, "depth" : 20 * millimeter, "oppositeDirection" : false });
    const u2 = newSketchOnPlane(context, id + "u2", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, -1, 0), vector(1, 0, 0)) });
    skLineSegment(u2, "l1", { "start" : vector(0, 0) * millimeter, "end" : vector(30, 0) * millimeter });
    skSolve(u2);
    extrude(context, id + "level", { "bodyType" : ExtendedToolBodyType.SURFACE, "surfaceEntities" : qOwnedByBody(qBodyType(qCreatedBy(id + "u2", EntityType.BODY), BodyType.WIRE), EntityType.EDGE), "endBound" : BoundingType.BLIND, "depth" : 20 * millimeter, "oppositeDirection" : true });
    const sp = newSketchOnPlane(context, id + "sp", { "sketchPlane" : plane(vector(0, 0, 30) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skLineSegment(sp, "l1", { "start" : vector(0, 10) * millimeter, "end" : vector(30, 10) * millimeter });
    skSolve(sp);
    faceBlend(context, id + "blend1", { "side1" : qOwnedByBody(qBodyType(qCreatedBy(id + "upright", EntityType.BODY), BodyType.SHEET), EntityType.FACE), "flipSide1" : true, "side2" : qOwnedByBody(qBodyType(qCreatedBy(id + "level", EntityType.BODY), BodyType.SHEET), EntityType.FACE), "flipSide2" : false, "radius" : 5 * millimeter, "propagation" : false, "crossSection" : FaceBlendCrossSection.SWEPT_PROFILE, "blendControlType" : BlendControlType.RADIUS, "asymmetric" : false, "crossSectionShape" : FaceBlendCrossSectionShape.CIRCULAR, "tangentHoldLines" : false, "conicHoldLines" : false, "hasCliffEdges" : false, "hasCaps" : false, "hasLimits" : false, "hasHelpPoint" : false, "trim" : FaceBlendTrimType.WALLS, "detach" : false, "showSelection" : false, "showIsocurves" : false, "spine" : qCreatedBy(id + "sp", EntityType.EDGE) });
    return { "faces" : surfaceProbe(context, qOwnedByBody(qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SHEET), EntityType.FACE)), "edges" : edgeProbe(context, qBodyType(qCreatedBy(id, EntityType.BODY), BodyType.SHEET)) };
}

